package testhooks

import (
	"net/http"
	"time"

	"github.com/gin-gonic/gin"

	"workspace/generated/access"
	"workspace/generated/db"
	"workspace/generated/email"
	"workspace/generated/scheduling"
)

type body struct {
	Now string `json:"now"`
	Run string `json:"run"`
}

// Routes mounts the hooks.
func Routes(r gin.IRouter, requests *db.Scope) {
	r.POST("/api/osl-hooks/timers/run", timersRun)
	r.POST("/api/osl-hooks/schedules/run", schedulesRun)
	r.GET("/api/osl-hooks/emails", emails)
	r.POST("/api/osl-hooks/rules/off", func(c *gin.Context) { rulesSwitch(c, true) })
	r.POST("/api/osl-hooks/rules/on", func(c *gin.Context) { rulesSwitch(c, false) })
	r.GET("/api/osl-hooks/tenancy/unbound", func(c *gin.Context) { tenancyUnbound(c, requests) })
}

// rulesSwitch switches the generated rule checks, so a walk can prove the policies alone hold.
func rulesSwitch(c *gin.Context, off bool) {
	access.SetRulesDisabled(off)
	state := "on"
	if off {
		state = "off"
	}
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"rules": state}})
}

// tenancyUnbound answers what the app role reads of every tenant table with no tenant bound.
func tenancyUnbound(c *gin.Context, requests *db.Scope) {
	tables, err := requests.Unbound(c.Request.Context())
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": gin.H{"code": "probe_failed", "message": err.Error()}})
		return
	}
	c.JSON(http.StatusOK, gin.H{"data": tables})
}

func readBody(c *gin.Context) body {
	var b body
	_ = c.ShouldBindJSON(&b)
	return b
}

// hookNow is the moment a hook runs at: the body's now, or the clock.
func hookNow(b body) time.Time {
	if t, err := time.Parse(time.RFC3339Nano, b.Now); err == nil {
		return t.UTC()
	}
	return time.Now().UTC()
}

func timersRun(c *gin.Context) {
	b := readBody(c)
	ran, err := scheduling.RunDueTimers(c.Request.Context(), hookNow(b))
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": gin.H{"code": "timer_failed", "message": err.Error()}})
		return
	}
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"ran": ran}})
}

func schedulesRun(c *gin.Context) {
	b := readBody(c)
	ran, err := scheduling.RunSchedulesFor(c.Request.Context(), b.Run, hookNow(b))
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": gin.H{"code": "schedule_failed", "message": err.Error()}})
		return
	}
	if ran == 0 {
		c.JSON(http.StatusBadRequest, gin.H{"error": gin.H{"code": "unknown_schedule", "message": "no schedule runs " + b.Run}})
		return
	}
	c.JSON(http.StatusOK, gin.H{"data": gin.H{"ran": ran}})
}

func emails(c *gin.Context) {
	to, subject := c.Query("to"), c.Query("subject")
	out := make([]gin.H, 0)
	for _, e := range email.Captured() {
		if (to != "" && e.To != to) || (subject != "" && !containsFold(e.Subject, subject)) {
			continue
		}
		out = append(out, gin.H{"to": e.To, "subject": e.Subject, "text": e.Text})
	}
	c.JSON(http.StatusOK, gin.H{"data": out})
}

func containsFold(haystack, needle string) bool {
	return len(needle) == 0 || indexOf(haystack, needle) >= 0
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}
